import buildTypeIcon from '@jetbrains/icons/buildType-20px.svg'
import confirm from '@jetbrains/ring-ui-built/components/confirm-service/confirm-service'
import Icon from '@jetbrains/ring-ui-built/components/icon'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {memo, useCallback} from 'react'
import {useSearchParams} from 'react-router'

import {useAppDispatch, useAppSelector} from '../../../../../../hooks/react-redux'
import {defaultPipelineJobAgent} from '../../../components/PipelineForm/useCreatePipeline'
import {usePipelineId} from '../../../hooks/pipeline'
import type {Job} from '../../../types'
import {isPipelinesEnabledInExclusiveMode} from '../../../utils/featureToggles'
import {
  useGenerateFreeJobId,
  useGenerateFreeJobName,
  useIsDebugRunning,
} from '../../EditPipelinePage.hooks'
import {getDraftJobs} from '../../EditPipelinePage.selectors'
import {jobLimits} from '../../EditPipelinePage.utils'
import {pipelineDraft} from '../../slices/EditPipelinePage.slices'

import styles from './AddJob.module.css'

export function useJobCount() {
  const pipelineId = usePipelineId()
  return useAppSelector(state => Object.keys(getDraftJobs(state, pipelineId) ?? {}).length)
}

export function useAddJob() {
  const dispatch = useAppDispatch()
  const id = usePipelineId()
  const generateFreeJobName = useGenerateFreeJobName()
  const generateFreeJobId = useGenerateFreeJobId()
  const jobCount = useJobCount()
  const [, setSearchParams] = useSearchParams()

  return useCallback(
    async (newJob?: {job: Job; jobId: string}) => {
      let proceed = true

      if (jobLimits.soft != null && jobLimits.soft > 0 && jobCount >= jobLimits.soft) {
        try {
          await confirm({
            text: 'Job count warning',
            description: `The pipeline editor is optimized to work with no more than ${jobLimits.soft} jobs.`,
            confirmLabel: 'Add job anyway',
            rejectLabel: 'Cancel',
          })
        } catch (e) {
          proceed = false
        }
      }

      if (proceed) {
        if (newJob != null) {
          dispatch(pipelineDraft.actions.addJob({id, jobId: newJob.jobId, job: newJob.job}))
          setSearchParams({edit: 'true', job: newJob.jobId})
          return newJob.jobId
        }

        const name = generateFreeJobName()
        const jobId = await generateFreeJobId(name)
        dispatch(
          pipelineDraft.actions.addJob({
            id,
            jobId,
            job: {
              name,
              ...(isPipelinesEnabledInExclusiveMode() ? {'runs-on': defaultPipelineJobAgent} : {}),
            },
          }),
        )
        setSearchParams({edit: 'true', job: jobId})
        return jobId
      }
      return null
    },
    [jobCount, generateFreeJobName, generateFreeJobId, dispatch, id, setSearchParams],
  )
}

function AddJob() {
  const jobCount = useJobCount()
  const onClick = useAddJob()
  const addClickHandler = useCallback(() => onClick(), [onClick])
  const isReadonly = useIsDebugRunning()

  const limited = jobCount >= jobLimits.hard

  const button = (
    <button
      type="button"
      onClick={addClickHandler}
      className={styles.button}
      disabled={limited || undefined || isReadonly}
    >
      <Icon glyph={buildTypeIcon} className={styles.icon} />
      <span>{'Add'}</span>
    </button>
  )

  return limited ? (
    <Tooltip delay={100} title={`Max number of jobs is ${jobLimits.hard}`}>
      {button}
    </Tooltip>
  ) : (
    button
  )
}

export default memo(AddJob)
