import bug from '@jetbrains/icons/bug.svg'
import restartBug from '@jetbrains/icons/restart-bug.svg'
import stop from '@jetbrains/icons/stop.svg'
import List from '@jetbrains/ring-ui-built/components/list/list'
import {skipToken} from '@reduxjs/toolkit/query'
import classNames from 'classnames'
import merge from 'lodash/merge'
import {useEffect, useMemo} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../hooks/react-redux'
import useMyId from '../../../../../../hooks/useMyId'
import {getSingleBuildArg} from '../../../../../../rest/builds'
import {getBuildLocator} from '../../../../../../rest/locators'
import {getBuildStatusIconFromBuild, getBuildStatusTypeFromBuild} from '../../../../../../selectors'
import {restApi} from '../../../../../../services/rest'
import type {BuildId} from '../../../../../../types'
import {
  subscribeOnAgentEvents,
  subscribeOnBuildTypeEvents,
  subscribeOnRunningBuild,
} from '../../../../../../utils/subscriber'
import {
  AGENT_REGISTERED,
  AGENT_UNREGISTERED,
  BUILD_FINISHED,
  BUILD_INTERRUPTED,
  BUILD_STARTED,
  BUILD_TYPE_REMOVED_FROM_QUEUE,
} from '../../../../../../utils/subscriptionEvents'
import {usePipelineId} from '../../../hooks/pipeline'
import {usePipelineDebugArg} from '../../../PipelineRunPage/PipelineRunPage.hooks'
import {useDebugJobActions, useIsDebugRunning} from '../../EditPipelinePage.hooks'
import {debug} from '../../slices/EditPipelinePage.slices'

import styles from './EditPipelineJob.module.css'

function usePipelineDebugJob(jobId?: BuildId | null) {
  const arg = usePipelineDebugArg()
  const {
    job,
    agentId,
    refetch: refetchRun,
  } = restApi.endpoints.getBuildNormalized.useQuery(jobId ? arg : skipToken, {
    selectFromResult: ({data}) => {
      const run = data?.entities?.builds?.[data?.result!]
      const currentJob = run?.['snapshot-dependencies']?.build?.find(build => build.id === jobId)
      return {
        job: currentJob,
        agentId: currentJob?.agent?.id,
      }
    },
  })

  const {headInternalId, refetch} = restApi.endpoints.getBuildNormalized.useQuery(
    jobId
      ? getSingleBuildArg(getBuildLocator(jobId), {
          withBuildTypeDetails: true,
        })
      : skipToken,
    {
      selectFromResult: ({data}) => {
        const run = data?.entities?.builds?.[data?.result!]
        const headId = run?.buildType
        return {
          headInternalId: data?.entities?.buildTypes?.[headId!]?.internalId,
        }
      },
    },
  )

  const myId = useMyId()
  const icon = getBuildStatusIconFromBuild(job, myId, false, true)
  const isRunning = job?.state === 'running'
  const dispatch = useAppDispatch()

  useEffect(
    () =>
      headInternalId && jobId
        ? subscribeOnBuildTypeEvents(
            headInternalId,
            [BUILD_TYPE_REMOVED_FROM_QUEUE, BUILD_STARTED, BUILD_FINISHED, BUILD_INTERRUPTED],
            refetch,
          )
        : undefined,
    [headInternalId, jobId, refetch],
  )

  useEffect(
    () =>
      agentId
        ? subscribeOnAgentEvents(agentId, [AGENT_REGISTERED, AGENT_UNREGISTERED], refetchRun)
        : undefined,
    [agentId, refetchRun],
  )

  useEffect(() => {
    if (isRunning && jobId) {
      return subscribeOnRunningBuild(jobId, data =>
        dispatch(
          restApi.util.updateQueryData('getBuildNormalized', arg, draft => {
            const draftRun = draft?.entities?.builds?.[draft?.result!]?.[
              'snapshot-dependencies'
            ]?.build?.find(build => build.id === jobId)
            merge(draftRun, data)
          }),
        ),
      )
    }
    return undefined
  }, [dispatch, jobId, isRunning, arg])

  return {
    job,
    icon,
  }
}

export function useDebuggingJob(id: string, debugJobId?: number) {
  const dispatch = useAppDispatch()
  const pipelineId = usePipelineId()
  const isDebugRunning = useIsDebugRunning()
  const {onDebug, onStopDebug} = useDebugJobActions(id)
  const {job: debugJob, icon: debugIcon} = usePipelineDebugJob(debugJobId)
  const jobStatusType = getBuildStatusTypeFromBuild(debugJob)
  const isDebugPanelOpen = useAppSelector(state => state.pipelines.debug[pipelineId]?.isPanelOpen)
  const currentDebugJobId = useAppSelector(state => state.pipelines.debug[pipelineId]?.jobId)
  const runId = useAppSelector(state => state.pipelines.debug[pipelineId]?.runId)
  const isJobDebugging = runId && currentDebugJobId === id

  const debugActions = useMemo(
    () => [
      !isDebugPanelOpen &&
        isJobDebugging && {
          label: 'Show debugger log',
          onClick: () => {
            dispatch(debug.actions.toggleOpenPanel({pipelineId, open: true}))
          },
        },
      isDebugRunning &&
        isJobDebugging && {
          label: 'Stop debug',
          className: styles.debugButton,
          glyph: stop,
          onClick: onStopDebug,
        },
      !isDebugRunning && {
        label: isJobDebugging ? 'Rerun debug' : 'Debug job',
        className: classNames({[styles.debugButton]: isDebugRunning}),
        glyph: isJobDebugging ? restartBug : bug,
        onClick: onDebug,
      },
      {
        rgItemType: List.ListProps.Type.SEPARATOR,
      },
    ],
    [isDebugRunning, isDebugPanelOpen, isJobDebugging, dispatch, pipelineId, onStopDebug, onDebug],
  )

  return {isDebugRunning, isJobDebugging, debugActions, debugJob, debugIcon, jobStatusType}
}
