import arrowLeftIcon from '@jetbrains/icons/arrow-left.svg'
import arrowRightIcon from '@jetbrains/icons/arrow-right.svg'
import duplicateIcon from '@jetbrains/icons/duplicate.svg'
import trashIcon from '@jetbrains/icons/trash.svg'
import updateIcon from '@jetbrains/icons/update.svg'
import DropdownMenu from '@jetbrains/ring-ui-built/components/dropdown-menu/dropdown-menu'
import {isTruthy} from '@jetbrains/ring-ui-built/components/global/typescript-utils'
import type {ListDataItemProps} from '@jetbrains/ring-ui-built/components/list/consts'
import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/list'
import List from '@jetbrains/ring-ui-built/components/list/list'
import ListItem from '@jetbrains/ring-ui-built/components/list/list__item'
import {IconButton, SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import deepEqual from 'fast-deep-equal'
import type * as React from 'react'
import {memo, useCallback, useMemo} from 'react'
import {graphql, useFragment} from 'react-relay'

import {useBuildStatusIconRelay} from '../../../../../../hooks/useBuildStatusIcon'
import Tooltip from '../../../../../common/Tooltip/Tooltip'
import JobIconStatus from '../../../components/JobIconStatus/JobIconStatus'
import JobTile, {JobTileType} from '../../../components/JobTile/JobTile'
import type {pipelineHeadBuildTypeFragment$key} from '../../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import {usePipelineId} from '../../../hooks/pipeline'
import usePermissionCanEditPipeline from '../../../hooks/usePermissionCanEditPipeline'
import PipelineRunJobProgress from '../../../PipelineRunPage/PipelineTab/PipelineRunChart/PipelineRunJob/PipelineRunJobProgress/PipelineRunJobProgress'
import {
  isTemporaryHideFailedJobStateEditMode,
  isTestDriveJobEnabled,
} from '../../../utils/featureToggles'
import {deleteJob} from '../../EditPipelinePage.actions'
import {
  useGenerateCloneJobNames,
  useIsJobDeleted,
  useLastRun,
  usePipelineDraftExistingJob,
} from '../../EditPipelinePage.hooks'
import {getJobName, makeTotalCountPipelineErrorsSelector} from '../../EditPipelinePage.selectors'
import {jobLimits} from '../../EditPipelinePage.utils'
import {
  useDependencies,
  useToggleDependency,
} from '../../SettingsSidebarContent/JobSettingsSidebar/JobDependencies/JobDependencies.hooks'
import {useDependencyFilesPublication} from '../../SettingsSidebarContent/JobSettingsSidebar/JobDependencies/JobDependency/JobDependency.hooks'
import {
  useNonDeletableReason,
  useNonRestorableReason,
} from '../../SettingsSidebarContent/JobSettingsSidebar/JobSettingsFooter/JobSettingsFooter'
import {pipelineDraft} from '../../slices/EditPipelinePage.slices'
import {useAddJob, useJobCount} from '../AddJob/AddJob'
import type {DrawingLine} from '../EditPipelineChart'

import type {EditPipelineJobLastRunFragment$key} from './__generated__/EditPipelineJobLastRunFragment.graphql'
import AddLine from './AddLine/AddLine'
import {useDebuggingJob} from './EditPipelineJob.hooks'
import {getJobIconClassName, getJobLabelClassName} from './EditPipelineJob.utils'

import styles from './EditPipelineJob.module.css'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

type Props = {
  id: string
  selected: boolean
  isNew?: boolean
  x: number
  y: number
  pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null
  withLabel?: boolean
  startDrawing?: (line: DrawingLine, e: React.MouseEvent) => void
  drawingLine?: DrawingLine | null
  warningMessage?: string | null
  readOnly?: boolean
  debugJobId?: number | undefined
}

const lastRunFragment = graphql`
  fragment EditPipelineJobLastRunFragment on Build {
    ...useBuildStatusIconFragment
    parallelized
    status
  }
`

function EditPipelineJob({
  id,
  selected,
  isNew = false,
  x,
  y,
  pipelineHeadBuildTypeKey,
  withLabel = true,
  startDrawing,
  drawingLine,
  warningMessage,
  readOnly,
  debugJobId,
}: Props) {
  const pipelineId = usePipelineId()
  const {canViewPipelineSettings, canEditPipeline} = usePermissionCanEditPipeline()
  const name = useAppSelector(state => getJobName(state, pipelineId, id))
  const isEdited = useAppSelector(state => {
    const {draft, original} = {...state.pipelines.pipelineDraft[pipelineId]}
    const draftJob = {...draft?.settings?.jobs?.[id]}
    const originalJob = original?.settings?.jobs?.[id]
    // Task: TCP-22 Rework "Use files..." link on Dependencies block
    // Hot fix: not detect changes in the Job file dependencies
    // Start
    const originalJobDependency = originalJob?.dependencies?.reduce<
      Record<string, Record<string, readonly string[]>>
    >((accumulator, value) => {
      if (typeof value === 'object') {
        return {
          ...accumulator,
          ...value,
        }
      }
      return accumulator
    }, {})

    draftJob?.dependencies?.forEach((dependency, index) => {
      if (typeof dependency === 'object') {
        const [jobId] = Object.keys(dependency)
        const originalDependency = originalJobDependency?.[jobId]
        if (originalDependency && draftJob?.dependencies?.[index]) {
          const dependencies = [...draftJob.dependencies]

          dependencies[index] = {
            [jobId]: originalDependency,
          }

          draftJob.dependencies = dependencies
        }
      }
    })
    // End
    // Hot fix: not detect changes in the Job file dependencies

    return !deepEqual(draftJob, originalJob)
  })
  const isHoveredInSidebar = useAppSelector(state => state.pipelines.hoveredJob === id)
  const nameIsEmpty = name == null || name.length === 0
  const isDeleted = useIsJobDeleted(id)
  const runKey = useLastRun(id, pipelineHeadBuildTypeKey)
  const run = useFragment<EditPipelineJobLastRunFragment$key>(lastRunFragment, runKey)
  const {isDebugRunning, isJobDebugging, debugActions, debugJob, debugIcon, jobStatusType} =
    useDebuggingJob(id, debugJobId)

  const selector = useMemo(() => makeTotalCountPipelineErrorsSelector(), [])
  const hasError = useAppSelector(
    state =>
      selector(state, {
        jobId: id,
        pipelineId,
      }) > 0,
  )
  const hasWarning = warningMessage != null
  const buildStatusIconRelay = useBuildStatusIconRelay(run)
  const statusIcon = isTemporaryHideFailedJobStateEditMode ? 'buildType-20px' : buildStatusIconRelay
  const icon = isDeleted ? 'trash' : run != null ? statusIcon : 'buildType-20px'
  const labelText = isDeleted
    ? 'Deleted'
    : selected
      ? 'Editing'
      : isEdited
        ? isNew
          ? 'New'
          : 'Edited'
        : null

  const topLeft = (
    <>
      <JobIconStatus
        parallelized={run?.parallelized}
        status={run?.status}
        icon={debugJob ? debugIcon : icon}
        className={getJobIconClassName({
          isSelected: selected,
          isNew,
          isEdited,
          isDeleted,
          hasWarning,
          hasError,
        })}
      />
      {withLabel && (
        <span className={getJobLabelClassName({hasError, hasWarning, isDeleted})}>{labelText}</span>
      )}
    </>
  )

  const {dependencies, possibleDependencies, dependants, possibleDependants} = useDependencies(id)
  const isDrawingTarget = drawingLine?.target === id
  const isDrawingSource = drawingLine?.source === id
  const onAddDependency = useCallback(
    (e: React.MouseEvent) => startDrawing?.({target: id}, e),
    [id, startDrawing],
  )
  const onAddDependant = useCallback(
    (e: React.MouseEvent) => startDrawing?.({source: id}, e),
    [id, startDrawing],
  )
  const jobCount = useJobCount()
  const limited = jobCount >= jobLimits.hard
  const nonDeletableReason = useNonDeletableReason(id)
  const nonRestoreableReason = useNonRestorableReason(id)
  const dispatch = useAppDispatch()
  const addJob = useAddJob()
  const job = usePipelineDraftExistingJob(id)!
  const generateCloneNames = useGenerateCloneJobNames({name})

  const toggleDependency = useToggleDependency()

  const actions: ListDataItem[] = [
    ...(isTestDriveJobEnabled && !isDeleted && (!isDebugRunning || isJobDebugging)
      ? debugActions
      : []),
    !isDeleted &&
      !limited && {
        key: 'clone',
        disabled: isDebugRunning,
        label: 'Duplicate job',
        glyph: duplicateIcon,
        onClick: async () => {
          const cloneNames = await generateCloneNames()
          await addJob({
            jobId: cloneNames.id,
            job: {
              ...job,
              name: cloneNames.name,
            },
          })
        },
      },
    !isDeleted &&
      !limited && {
        label: 'Create job after',
        glyph: arrowRightIcon,
        disabled: isDebugRunning,
        onClick: async () => {
          const jobId = await addJob()
          if (jobId != null) {
            toggleDependency(jobId, id, true)
          }
        },
      },
    !isDeleted &&
      !limited && {
        label: 'Create job before',
        glyph: arrowLeftIcon,
        disabled: isDebugRunning,
        onClick: async () => {
          const jobId = await addJob()
          if (jobId != null) {
            toggleDependency(id, jobId, true)
          }
        },
      },
    !isDeleted &&
      !limited && {
        key: 'separator',
        rgItemType: List.ListProps.Type.SEPARATOR,
      },
    !isDeleted && {
      key: 'delete',
      rgItemType: List.ListProps.Type.CUSTOM,
      template: (props: ListDataItemProps) => {
        const commonProps = {
          ...props,
          label: 'Delete Job',
          glyph: trashIcon,
          onClick: () => dispatch(deleteJob({id: pipelineId, jobId: id})),
        }
        return nonDeletableReason != null || isDebugRunning ? (
          <Tooltip
            className={styles.tooltip}
            title={nonDeletableReason}
            onClick={e => e.stopPropagation()}
          >
            <ListItem
              {...commonProps}
              disabled
              className={classNames(styles.delete, styles.disabled)}
            />
          </Tooltip>
        ) : (
          <ListItem {...commonProps} className={styles.delete} />
        )
      },
      className: styles.actionWrapper,
    },
    isDeleted && {
      key: 'restore',
      label:
        nonRestoreableReason != null ? (
          <Tooltip
            className={styles.tooltip}
            title={nonRestoreableReason}
            onClick={e => e.stopPropagation()}
          >
            {'Restore job'}
          </Tooltip>
        ) : (
          'Restore job'
        ),
      disabled: nonRestoreableReason != null || isDebugRunning,
      className: classNames({[styles.disabled]: nonRestoreableReason != null || isDebugRunning}),
      glyph: updateIcon,
      onClick: () => dispatch(pipelineDraft.actions.restoreJob({id: pipelineId, jobId: id})),
    },
  ].filter(isTruthy)
  const files = useDependencyFilesPublication(id).filter(Boolean)

  const runningInfo = debugJob?.['running-info']
  const {percentageComplete} = runningInfo ?? {}
  const jobProgress = percentageComplete ? (
    <PipelineRunJobProgress mainPercentage={percentageComplete} status={jobStatusType} />
  ) : null

  return (
    <div className={styles.container} style={{top: y, left: x}}>
      <JobTile
        className={classNames(styles.job, {[styles.debug]: isDebugRunning})}
        to={canViewPipelineSettings ? {search: `edit=true&job=${encodeURIComponent(id)}`} : ''}
        title={
          canEditPipeline
            ? `Edit job ${name}`
            : canViewPipelineSettings
              ? `View job ${name} settings`
              : undefined
        }
        name={nameIsEmpty ? (selected ? 'Enter the name' : 'Unnamed job') : name}
        progress={jobProgress}
        topLeft={topLeft}
        topRight={
          !readOnly &&
          (files.length > 0 || actions.length > 0) && (
            <>
              {files.length > 0 && (
                <Tooltip title="This job produces artifacts">
                  <SvgIcon icon="artifacts" className={styles.hasArtifacts} />
                </Tooltip>
              )}
              {actions.length > 0 && (
                <div
                  role="presentation"
                  onClick={e => {
                    e.preventDefault()
                    e.stopPropagation()
                  }}
                >
                  <DropdownMenu
                    anchor={
                      <IconButton
                        className={styles.actions}
                        title=""
                        aria-label="Actions"
                        icon="more-options"
                      />
                    }
                    data={actions}
                  />
                </div>
              )}
            </>
          )
        }
        type={hasError ? JobTileType.ERROR : hasWarning ? JobTileType.WARNING : JobTileType.DEFAULT}
        status={
          hasError ? (
            <span className={styles.errorMessage}>{'Settings error'}</span>
          ) : (
            hasWarning && <span className={styles.warningMessage}>{warningMessage}</span>
          )
        }
        selected={selected}
        deleted={isDeleted}
        hovered={isHoveredInSidebar || isDrawingTarget || isDrawingSource}
      >
        {!readOnly &&
          !isDeleted &&
          !isDebugRunning &&
          [...possibleDependencies].some(depId => !dependencies.has(depId)) && (
            <AddLine
              className={styles.addDependency}
              direction="from"
              onMouseDown={onAddDependency}
              disabled={drawingLine != null && !isDrawingTarget}
              selected={isDrawingTarget}
            />
          )}
        {!readOnly &&
          !isDeleted &&
          !isDebugRunning &&
          [...possibleDependants].some(depId => !dependants.has(depId)) && (
            <AddLine
              className={styles.addDependant}
              direction="to"
              onMouseDown={onAddDependant}
              disabled={drawingLine != null && !isDrawingSource}
              selected={isDrawingSource}
            />
          )}
      </JobTile>
    </div>
  )
}

export default memo(EditPipelineJob)
