import alertService from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import type {FetchBaseQueryError} from '@reduxjs/toolkit/query'
import {useCallback, useEffect, useState} from 'react'
import {useNavigate} from 'react-router'

import {getPipelineHref} from '../../../../../routes'
import {getExtractErrorMessage} from '../../EditPipelinePage/EditPipelinePage.utils'
import {ALL_BRANCHES} from '../../EditPipelinePage/SettingsSidebarContent/PipelineSettingsTriggerSidebar/PipelineOnChangesTriggerForm/PipelineOnChangesTriggerForm.const'
import {pipelinesApi} from '../../services/pipelinesApi'
import type {NewVcsRootDto} from '../../services/pipelinesApi.types'
import {instanceOf} from '../../types'
import {
  isPipelinesEnabledInExclusiveMode,
  isPullRequestsFeatureEnabled,
} from '../../utils/featureToggles'

function processError(error: unknown) {
  let errorText = (error instanceof Error && error.message) || 'Failed to create new pipeline'
  if (instanceOf<FetchBaseQueryError>(error, 'status')) {
    errorText = getExtractErrorMessage(error)
  }
  alertService.error(errorText)
}

type CreatePipelineArg = {
  pipelineName: string
  repositoryUrl?: string
  branch?: string
  branchSpecification?: string
  trackPullRequests?: boolean
  isPrivate?: boolean
  connectionId?: string
  password?: string
  username?: string
  sshKey?: {
    name: string
    passphrase?: string
  }
  parentProjectId?: string
  externalVcsRootId?: string
  isExternal?: boolean
}

const defaultPipelineJobName = 'Job 1'
const defaultPipelineJobId = 'Job1'
export const defaultPipelineJobAgent = 'Linux-Medium'

export default function useCreatePipeline(): {
  createPipeline: (arg: CreatePipelineArg) => void
  pipelineCreating: boolean
} {
  const [pipelineCreating, setPipelineCreating] = useState<boolean>(false)
  const [createNewPipeline, {error}] = pipelinesApi.endpoints.createNewPipeline.useMutation()

  useEffect(() => {
    if (error) {
      processError(error)
    }
  }, [error])
  const navigate = useNavigate()

  const createPipeline = useCallback(
    async ({
      pipelineName,
      repositoryUrl,
      branch,
      branchSpecification,
      trackPullRequests,
      isPrivate,
      connectionId,
      username,
      password,
      sshKey,
      parentProjectId,
      externalVcsRootId,
    }: CreatePipelineArg) => {
      setPipelineCreating(true)
      try {
        const pipelineResult = await createNewPipeline({
          body: {
            settings: {
              jobs: {
                [defaultPipelineJobId]: {
                  name: defaultPipelineJobName,
                  steps: [],
                  ...(isPipelinesEnabledInExclusiveMode()
                    ? {'runs-on': defaultPipelineJobAgent}
                    : {}),
                },
              },
            },
            additionalVcsRoots: [],
            name: pipelineName,
            vcsRoot: {
              externalVcsRootId,
              url: repositoryUrl,
              branch,
              branchSpecification,
              trackPullRequests,
              vcsName: externalVcsRootId == null ? 'jetbrains.git' : undefined,
              isPrivate,
              connectionId,
              username,
              password,
              sshKey,
            } as NewVcsRootDto,
            triggers: [
              {
                type: 'vcsTrigger',
                ...(isPullRequestsFeatureEnabled
                  ? {
                      parameters: {
                        branchFilter: ALL_BRANCHES,
                      },
                      triggerBranches: true,
                      triggerPullRequests: false,
                    }
                  : {parameters: {}}),
              },
            ],
            notifications: [],
          },
          parentProjectId,
        })
        if ('data' in pipelineResult && pipelineResult.data != null) {
          navigate(
            `${getPipelineHref(pipelineResult.data.id)}?edit=true&job=${defaultPipelineJobId}`,
            {
              state: {
                isCreated: true,
              },
            },
          )
        }
      } catch (e) {
        processError(e)
      } finally {
        setPipelineCreating(false)
      }
    },
    [createNewPipeline, navigate],
  )

  return {pipelineCreating, createPipeline}
}
