import classNames from 'classnames'

import styles from './EditPipelineJob.module.css'

export function getJobIconClassName({
  hasWarning,
  hasError,
  isSelected,
  isNew,
  isEdited,
  isDeleted,
}: {
  hasWarning: boolean
  hasError: boolean
  isSelected: boolean
  isNew: boolean
  isEdited: boolean
  isDeleted: boolean
}) {
  let className = styles.default
  if (hasError) {
    className = styles.error
  } else if (hasWarning) {
    className = styles.warning
  } else if ((isSelected || isNew || isEdited) && !isDeleted) {
    className = styles.main
  }

  return classNames(styles.icon, className)
}

export function getJobLabelClassName({
  hasError,
  hasWarning,
  isDeleted,
}: {
  hasError: boolean
  hasWarning: boolean
  isDeleted: boolean
}) {
  let className = styles.main
  if (hasError) {
    className = styles.errorMessage
  } else if (hasWarning) {
    className = styles.warningMessage
  } else if (isDeleted) {
    className = styles.deleted
  }

  return classNames(styles.label, className)
}
