import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {memo} from 'react'

import Tooltip from '../../../../../../common/Tooltip/Tooltip'
import {usePipelineId} from '../../../../hooks/pipeline'
import {deleteJob} from '../../../EditPipelinePage.actions'
import {
  useHasNonDeletedDependants,
  useIsDebugRunning,
  useIsJobDeleted,
  useNonDeletedPipelineJobIdsOrDraft,
  usePipelineDraftGraph,
} from '../../../EditPipelinePage.hooks'
import {pipelineDraft} from '../../../slices/EditPipelinePage.slices'
import SidebarFooter from '../../SidebarFooter/SidebarFooter'

import styles from './JobSettingsFooter.module.css'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

type Props = {
  jobId: string
}

export function useNonDeletableReason(jobId: string) {
  const hasNonDeletedDependants = useHasNonDeletedDependants(jobId)
  const isDebugRunning = useIsDebugRunning()
  const isSingleJob = useNonDeletedPipelineJobIdsOrDraft().length === 1

  if (isDebugRunning) {
    return 'Job settings cannot be edited during a debug run. Stop the debug session or wait for it to finish'
  }

  return isSingleJob
    ? "Can't delete the only job"
    : hasNonDeletedDependants
      ? 'Some jobs depend on this one'
      : undefined
}

export function useNonRestorableReason(jobId: string) {
  const graph = usePipelineDraftGraph()
  const pipelineId = usePipelineId()
  const deleted = useAppSelector(state => state.pipelines.pipelineDraft[pipelineId]?.deleted?.jobs)
  const hasDeletedDependencies =
    graph[jobId] != null &&
    Array.from(graph[jobId].dependencies).some(dependencyId => deleted?.includes(dependencyId))
  return hasDeletedDependencies ? 'This job depends on some deleted ones' : undefined
}

function JobSettingsFooter({jobId}: Props) {
  const dispatch = useAppDispatch()

  const pipelineId = usePipelineId()

  const isDeleted = useIsJobDeleted(jobId)

  const handlerJobDeleteClick = () => dispatch(deleteJob({id: pipelineId, jobId}))
  const handlerJobRestoreClick = () =>
    dispatch(pipelineDraft.actions.restoreJob({id: pipelineId, jobId}))

  const icon = isDeleted ? 'update' : 'trash'
  const clickHandler = isDeleted ? handlerJobRestoreClick : handlerJobDeleteClick
  const title = isDeleted ? 'Restore job' : 'Delete job'

  const nonDeletableReason = useNonDeletableReason(jobId)
  const nonRestorableReason = useNonRestorableReason(jobId)

  const disabledReason = isDeleted ? nonRestorableReason : nonDeletableReason
  const isDisabled = disabledReason != null

  const button = (
    <IconButton
      className={classNames({
        [styles.restoreJob]: isDeleted,
      })}
      iconClassName={classNames({
        [styles.restoreJobIcon]: isDeleted,
        [styles.disabled]: isDisabled,
      })}
      title={title}
      icon={icon}
      onClick={clickHandler}
      danger={!isDeleted}
      disabled={isDisabled}
    >
      {title}
    </IconButton>
  )

  return (
    <SidebarFooter>
      {isDeleted && <span>{'Job deleted'}</span>}
      {disabledReason != null ? <Tooltip title={disabledReason}>{button}</Tooltip> : button}
    </SidebarFooter>
  )
}

export default memo(JobSettingsFooter)
