import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {memo} from 'react'

import Tooltip from '../../../../../../common/Tooltip/Tooltip'

import styles from './AddLine.module.css'

type Props = {
  className?: string
  direction: 'from' | 'to'
  onMouseDown?: (e: React.MouseEvent) => void
  disabled?: boolean
  selected?: boolean
}

function AddLine({className, direction, onMouseDown, disabled, selected}: Props) {
  return (
    <Tooltip
      className={classNames({[styles.disabled]: disabled})}
      title={
        <>
          {`Add dependency ${direction} this job`}
          <span className={styles.hintAction}>{'Drag/Click'}</span>
        </>
      }
    >
      <IconButton
        icon="add-circle"
        aria-label="Add line"
        title=""
        className={classNames(styles.addLine, className, {[styles.selected]: selected})}
        iconClassName={styles.icon}
        onMouseDown={onMouseDown}
        onClick={e => {
          e.preventDefault()
          e.stopPropagation()
        }}
      />
    </Tooltip>
  )
}

export default memo(AddLine)
